/**
 * Motore di ricerca e query semantiche ad alta precisione
 */
esporta la funzione asincrona searchSentences(
  query: stringa,
  filtri: SearchFilterOptions = {}
): Promessa<{ risultati: FraseItem[]; totale:numero; semanticMatches?: SemanticExplanationMatch[] }> {
  const all = attendono loadSentences();
  const normalizedQuery = normalizeText(query);
  const queryTokens = normalizedQuery ? normalizedQuery.split(' ').filter(Booleano) : [];

  cost {
    cefr = 'tutto',
    sezione = 'tutto',
    categoria = 'tutti',
    sottocategoria = 'tutti',
    grammatica = 'tutto',
    formalità = 'tutto',
    limite = 50,
    scostamento = 0,
  } = filtri;

  // Passaggio del filtro
  lascia filtrato = all.filter(s => {
    if (cefr !== 'all' && s.cefr !== cefr) return false;
    if (sezione !== 'all' && s.sezione !==sezione) return false;
    if (categoria !== 'tutti' && s.categoria !== categoria) return false;
    if (sottocategoria !== 'tutti' && s.sottocategoria !== sottocategoria) return false;
    if (grammar !== 'all' && !s.grammar.toLowerCase().includes(grammar.toLowerCase())) return false;
    if (formality !== 'all' && s.formality.toLowerCase() !== formality.toLowerCase()) return false;
    restituisce vero;
  });

  if (!normalizedQuery) {
    const totale = lunghezza.filtrata;
    const impaginato = filtrato. slice(offset, offset + limite);
    return {risultati: impaginati, totali};
  }

  // Algoritmo di punteggio
  interfacciaScoredItem {
    elemento: Elemento frase;
    punteggio:numero;
    aspetto: SemanticExplanationMatch['matchedAspect'];
  }

  const con punteggio: ScoredItem[] = [];

  for (const s of filtered) {
    lascia che il punteggio sia = 0;
    let matchedAspect: SemanticExplanationMatch['matchedAspect'] = 'english';

    const normEn = normalizeText(s.english);
    const normEg = normalizeText(s.arabicEg);
    const normFusha = normalizeText(s.arabicFusha);
    const normGrammar = normalizeText(s.grammar);
    const normaScopo = normalizzaTesto(s.scopo);

    // Corrispondenza esatta dell'intera frase
    if (normEn === normalizedQuery) {
      punteggio += 100;
      matchedAspect = 'inglese';
    } else if (normEg === normalizedQuery) {
      punteggio += 95;
      matchedAspect = 'arabo-eg';
    } altrimenti se (normFusha === normalizedQuery) {
      punteggio += 90;
      matchedAspect = 'arabo-fusha';
    }

    //La sottostringa contiene
    if (normEn.includes(normalizedQuery)) {
      punteggio += 50;
      matchedAspect = 'inglese';
    } altrimenti se (normEg.includes(normalizedQuery)) {
      punteggio += 45;
      matchedAspect = 'arabo-eg';
    } altrimenti se (normFusha.includes(normalizedQuery)) {
      punteggio += 40;
      matchedAspect = 'arabo-fusha';
    } altrimenti se (normGrammar.includes(normalizedQuery)) {
      punteggio += 35;
      matchedAspect = 'grammatica';
    } altrimenti se (normPurpose.includes(normalizedQuery)) {
      punteggio += 30;
      matchedAspect = 'concetto';
    }

    // Corrispondenza del token
    lascia che tokenMatches = 0;
    for (token const di queryTokens) {
      if (normEn.includes(token)) tokenMatches += 5;
      if (normEg.includes(token)) tokenMatches += 4;
      if (normFusha.includes(token)) tokenMatches += 3;
      if (s.vocabulary.some(v => normalizeText(v).includes(token))) tokenMatches += 4;
      if (s.tags.some(t => normalizeText(t).includes(token))) tokenMatches += 3;
    }
    punteggio += tokenMatches;

    se (punteggio > 0) {
      score.push({ elemento: s, punteggio, aspetto: matchedAspect });
    }
  }

  punteggio.sort((a, b) => b.punteggio - a.punteggio);

  // La spiegazione semantica corrisponde agli elementi principali
  const semanticMatches: SemanticExplanationMatch[] = score.slice(0, 5).map(s => {
    lascia sfumatura = '';
    if (s.item.grammar.toLowerCase().includes('past continue')) {
      sfumatura = 'Il passato continuo mostra che un evento era in corso in un momento specifico nel passato.';
    } else if (s.item.grammar.toLowerCase().includes('present Perfect Continuous')) {
      sfumatura = 'Il presente perfetto continuo enfatizza il tempo del passato e continua fino al momento in cui si parla.';
    } else if (s.item.grammar.toLowerCase().includes('futuro perfetto')) {
      sfumatura = 'Il futuro prossimo esprime che un evento sarà completato prima di un momento specifico nel futuro.';
    } else if (s.item.grammar.toLowerCase().includes('indirect')) {
      sfumatura = 'La forma della richiesta indiretta è l'apice dell'etichetta diplomatica nella comunicazione inglese.';
    }
    ritorno {
      frase: s.item,
      similarityScore: Math.min(100, s.score),
      sfumaturaSpiegazioneAr: sfumatura,
      matchedAspect: s.aspect,
    };
  });

  const totale = segnato. lunghezza;
  const impaginato = score.slice(offset, offset + limite).map(s => s.item);

  ritorno {
    risultati: impaginati,
    totale,
    corrispondenze semantiche,
  };
}

